*/_jsxs(Link,{className:"nt-btn nt-btn-ghost",to:"/certificado/".concat(id),"data-testid":"cert-page-link",children:[/*#__PURE__*/_jsx(ExternalLink,{size:14,strokeWidth:1.5})," ",t('ag.publicCert')]})]})]})]}),/*#__PURE__*/_jsxs("aside",{className:"nt-chat","data-testid":"chat-panel",children:[/*#__PURE__*/_jsxs("div",{className:"nt-chat-head",children:[/*#__PURE__*/_jsx(Lock,{size:11,strokeWidth:1.5,style:{verticalAlign:'-1px',marginRight:5}}),t('ag.chatHead'),frozen?t('ag.chatFrozenSuffix'):'',!frozen&&sharedKey&&/*#__PURE__*/_jsx("span",{"data-testid":"chat-e2e-badge",style:{marginLeft:6,color:'var(--seal)',fontSize:10,fontWeight:700},title:pqActive?'X-Wing: ML-KEM-768 + X25519 (post-quantum hybrid)':'ECDH P-256',children:pqActive?'● E2E·PQ':'● E2E'})]}),/*#__PURE__*/_jsxs("div",{className:"nt-chat-body",children:[view.length===0&&/*#__PURE__*/_jsx("div",{className:"nt-note",style:{textAlign:'center',margin:'auto'},children:t('ag.chatEmpty')}),view.map((m,i)=>/*#__PURE__*/_jsxs("div",{className:"nt-msg ".concat(m.sender===(user===null||user===void 0?void 0:user.email)?'nt-msg-me':'nt-msg-them'),"data-testid":"chat-message",children:[m.locked?/*#__PURE__*/_jsxs("span",{style:{opacity:0.6,fontStyle:'italic'},"data-testid":"chat-message-locked",children:[/*#__PURE__*/_jsx(Lock,{size:11,strokeWidth:1.5,style:{verticalAlign:'-1px',marginRight:4}}),t('ag.msgLocked')]}):m.text,/*#__PURE__*/_jsxs("span",{className:"t",children:[m.sender===(user===null||user===void 0?void 0:user.email)?t('ag.you'):m.sender," \xB7 ",new Date(m.ts).toLocaleString(locale,{hour:'2-digit',minute:'2-digit',day:'2-digit',month:'2-digit'})]})]},i)),/*#__PURE__*/_jsx("div",{ref:chatEndRef})]}),frozen?/*#__PURE__*/_jsx("div",{className:"nt-chat-input",style:{justifyContent:'center'},children:/*#__PURE__*/_jsx("span",{className:"nt-note nt-mono","data-testid":"chat-frozen-note",children:t('ag.chatFrozenNote')})}):!sharedKey?/*#__PURE__*/_jsx("div",{className:"nt-chat-input",style:{justifyContent:'ce